export function formatCents(cents) {
	const sign = cents < 0 ? "-" : "";
	const abs = Math.abs(cents);
	const whole = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+$)/g, ",");
	return `${sign}${whole}.${String(abs % 100).padStart(2, "0")}`;
}

export function renderReport(totals) {
	if (!Array.isArray(totals)) throw new TypeError("totals must be an array");
	const total = totals.reduce((sum, t) => sum + t.cents, 0);
	const amounts = totals.map((t) => formatCents(t.cents));
	const totalText = formatCents(total);
	const keyWidth = Math.max(5, totals.length > 0 ? totals[0].key.length : 0);
	const amountWidth = Math.max(totalText.length, ...amounts.map((a) => a.length));
	const line = (key, amount) => `${key.padEnd(keyWidth)} | ${amount.padStart(amountWidth)}`;
	const lines = totals.map((t, i) => line(t.key, amounts[i]));
	lines.push("-".repeat(keyWidth + 3 + amountWidth));
	lines.push(line("TOTAL", totalText));
	return lines.join("\n");
}

const isBlank = (ch) => ch === " " || ch === "\t";

export function parseCsvLine(line) {
	const fields = [];
	const n = line.length;
	let i = 0;
	for (;;) {
		while (i < n && isBlank(line[i])) i++;
		if (line[i] === '"') {
			i++;
			let value = "";
			for (;;) {
				if (i >= n) throw new SyntaxError("unterminated quote");
				if (line[i] === '"') {
					i++;
					break;
				}
				value += line[i++];
			}
			while (i < n && isBlank(line[i])) i++;
			if (i < n && line[i] !== ",") throw new SyntaxError("text after closing quote");
			fields.push(value);
		} else {
			let j = line.indexOf(",", i);
			if (j === -1) j = n;
			fields.push(line.slice(i, j).replace(/[ \t]+$/, ""));
			i = j;
		}
		if (i >= n) break;
		i++;
	}
	return fields;
}

export function parseCsv(text) {
	if (typeof text !== "string") throw new TypeError("text must be a string");
	const lines = text.split(/\r?\n/);
	let header;
	const rows = [];
	lines.forEach((line, index) => {
		if (line === "") return;
		const fields = parseCsvLine(line);
		if (header === undefined) {
			header = fields;
			return;
		}
		if (fields.length !== header.length) {
			throw new RangeError(`line ${index + 1}: expected ${header.length} fields, got ${fields.length}`);
		}
		rows.push(Object.fromEntries(header.map((name, k) => [name, fields[k]])));
	});
	return rows;
}

const AMOUNT = /^-?\d+(\.\d{1,2})?$/;

export function groupTotals(rows, keyField, valueField) {
	const sums = new Map();
	for (const row of rows) {
		const key = row[keyField];
		const value = row[valueField];
		if (typeof key !== "string") throw new TypeError("key must be a string");
		if (typeof value !== "string" || !AMOUNT.test(value)) throw new TypeError(`bad amount: ${value}`);
		sums.set(key, (sums.get(key) ?? 0) + Math.floor(Number(value) * 100));
	}
	return [...sums]
		.map(([key, cents]) => ({ key, cents }))
		.sort((a, b) => b.cents - a.cents || (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { groupTotals } from "../src/aggregate.js";
import { parseCsv, parseCsvLine } from "../src/csv.js";
import { renderReport } from "../src/report.js";

test("parses a simple line and file", () => {
	assert.deepEqual(parseCsvLine("a, b ,c"), ["a", "b", "c"]);
	assert.deepEqual(parseCsv("k,v\nx,1\n\ny,2\n"), [
		{ k: "x", v: "1" },
		{ k: "y", v: "2" },
	]);
});

test("groups and renders", () => {
	const totals = groupTotals(
		[
			{ k: "a", v: "10.50" },
			{ k: "b", v: "3" },
			{ k: "a", v: "1.25" },
		],
		"k",
		"v",
	);
	assert.deepEqual(totals, [
		{ key: "a", cents: 1175 },
		{ key: "b", cents: 300 },
	]);
	assert.equal(renderReport(totals), "a     | 11.75\nb     |  3.00\n-------------\nTOTAL | 14.75");
});

